"""
Bilibili RAG 知识库系统

会话管理服务 - 统一处理用户会话的内存与数据库持久化逻辑
"""
from typing import Dict, Optional
from sqlalchemy.ext.asyncio import AsyncSession
from sqlalchemy import select
from app.models import UserSession as UserSessionModel
from loguru import logger


class SessionService:
    """会话服务，统一管理登录会话的读写逻辑"""

    def __init__(self, memory_store: Optional[Dict[str, dict]] = None):
        self._memory_store = memory_store or {}

    async def get_session_from_db(
        self, db: AsyncSession, session_id: str
    ) -> Optional[UserSessionModel]:
        """从数据库获取会话记录"""
        result = await db.execute(
            select(UserSessionModel).where(UserSessionModel.session_id == session_id)
        )
        return result.scalar_one_or_none()

    async def get_session(
        self, db: Optional[AsyncSession], session_id: str
    ) -> Optional[Dict]:
        """优先从内存缓存获取，否则从数据库加载并缓存"""
        # 内存缓存
        if session_id in self._memory_store:
            return self._memory_store[session_id]

        if db is None:
            return None

        # 数据库加载
        db_session = await self.get_session_from_db(db, session_id)
        if not db_session or not db_session.is_valid:
            return None

        session = {
            "cookies": {
                "SESSDATA": db_session.sessdata,
                "bili_jct": db_session.bili_jct,
                "DedeUserID": db_session.dedeuserid,
            },
            "user_info": {
                "mid": db_session.bili_mid,
                "uname": db_session.bili_uname,
                "face": db_session.bili_face,
            },
        }

        # 写入内存缓存
        self._memory_store[session_id] = session
        return session

    def set_session(self, session_id: str, session: Dict) -> None:
        """设置会话到内存缓存"""
        self._memory_store[session_id] = session

    def delete_session(self, session_id: str) -> None:
        """删除内存缓存中的会话"""
        self._memory_store.pop(session_id, None)

    def clear_qrcode_key(self, qrcode_key: str) -> None:
        """清理二维码临时键"""
        self._memory_store.pop(qrcode_key, None)
